{"command": "cat > /tmp/fix_kernel.py << 'EOF'
import sys

with open('/tmp/kernel_original.txt', 'r') as f:
    lines = f.readlines()

# Find line with idx_tokens = tl.arange(0, NP2_STATELEN)
for i, line in enumerate(lines):
    if 'idx_tokens = tl.arange(0, NP2_STATELEN)' in line:
        idx_tokens_line = i
        break
else:
    idx_tokens_line = None

# Find line with "((idx_tokens + 1) * stride_conv_state_tok)[:, None]"
for i, line in enumerate(lines):
    if '((idx_tokens + 1) * stride_conv_state_tok)[:, None]' in line:
        shift_line = i
        break
else:
    shift_line = None

# Find comment lines before shift_line
comment_start = None
for i in range(shift_line - 5, shift_line):
    if i >=0 and 'The conv_state updates works in a sliding window manner' in lines[i]:
        comment_start = i
        break

print(f"idx_tokens_line {idx_tokens_line}, shift_line {shift_line}, comment_start {comment_start}")

if idx_tokens_line is not None:
    # Insert shift definition after idx_tokens line
    lines.insert(idx_tokens_line + 1, "    shift = 1 if IS_SPEC_DECODING else seqlen\n")

# Update comment lines
if comment_start is not None:
    lines[comment_start] = "    # The conv_state updates works in a sliding window manner,\n"
    lines[comment_start + 1] = "    # at each forward pass, the tokens are shift by shift, so we\n"
    lines[comment_start + 2] = "    # load since idx_tokens + shift.\n"

# Replace shift offset line
if shift_line is not None:
    lines[shift_line] = lines[shift_line].replace('idx_tokens + 1', 'idx_tokens + shift')

# Output modified kernel
sys.stdout.write(''.join(lines))
EOF"}

